public class TallyCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        TallyCounter t = new TallyCounter();
        check("new counter starts at 0", 0, t.getCount());

        t.increment();
        t.increment();
        t.increment();
        check("three increments -> 3", 3, t.getCount());

        t.decrement();
        check("one decrement -> 2", 2, t.getCount());

        t.reset();
        check("reset -> 0", 0, t.getCount());

        t.decrement();
        check("decrement at 0 stays 0", 0, t.getCount());

        t.decrement();
        t.decrement();
        check("repeated decrements at 0 stay 0", 0, t.getCount());

        t.increment();
        check("counter still works after floor hit", 1, t.getCount());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

